#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_new_game_from_words_valid_input(void) {
    // Setup: valid words array with non-NULL strings
    const char *words[] = {"apple", "banana", "cherry"};
    int num_words = 3;

    // Seed random number generator to ensure deterministic test
    srand(12345); // Fixed seed for reproducibility

    // Test: call function under test
    struct game_instance game = new_game_from_words(words, num_words);

    // Assertions: verify game instance is initialized (not zero-initialized)
    // Since init_game_instance is called, we expect the game to have a valid state.
    // We cannot know which word was selected, but we can check that the game is not zeroed.
    // Check that size is set (should be > 0 for any of the words)
    TEST_ASSERT_TRUE(game.size > 0);
    // Check that current_word is not empty (first character is not null terminator)
    TEST_ASSERT_TRUE(game.current_word[0] != '\0');
    // Check that incorrect guesses start at 0
    TEST_ASSERT_EQUAL_INT(0, game.incorrect);
    // Check that guesses_size starts at 0
    TEST_ASSERT_EQUAL_INT(0, game.guesses_size);
    // Check that hidden array is initialized (all zeros)
    int i;
    for (i = 0; i < game.size; i++) {
        TEST_ASSERT_EQUAL_INT(0, game.hidden[i]);
    }

    // Cleanup: no dynamic memory to free (struct returned by value)
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_new_game_from_words_valid_input);
    return UNITY_END();
}

